    async def wim_buddyLis_copyBuddyLists(self, t: str, ta: str, f: str = "json") -> dict:
        """
        Скопируйте весь список друзей и все настройки на основе хостинга из одной учетной записи в другую.
        Существующий список друзей и все настройки на основе хостинга в учетной записи для копирования будут полностью
        заменены. Сложность этого метода заключается в том, что необходимо предоставить два веб-токена аутентификации.
        :param t: Target aimId, only used in trusted mode
        :param ta: Target token, where the source users buddylist should be copied to
        :param f: str [Required] The format of the data returned
        :return: тело ответа сервера
        """
        return await self.get(
            "wim/buddylist/copyBuddyLists",
            aimsid=self.aimsid,
            r=self.getReqId(),
            t=t,
            ta=ta,
            f=f,
        )

