    async def wim_buddyLis_getWatchers(
        self, t: str, f: str = "json", **kwargs: Unpack[WimBuddyListGetWatchersKwargs]
    ) -> dict:
        """
        Получить список наблюдателей
        :param t: Buddy name, multiple t= parameters are allowed
        :param f: str [Required] The format of the data returned
        param filter: str data filter, multiple can be handled. Example filter=ts=1234567(unix timestamp),
        numWatchers=100,t=targetname. Valid fields of filter are ts, numWatchers and t. All filter fields are comma
        separated. Note that in addition to any URL encoding needed to get special characters into a field value,
        the resulting value must be URL encoded for sending. The actual value for the example filter will be
        ts%3D1234567%2CnumWatchers%3D100%2Ct%3Dtargetname
        param nToSkip: int Skip number of watchers for this request
        param nToGet: int Number of watchers to get
        param sortOrder: Specify order of returned watcher list
        param enforcePrivacy: bool [Default 1]. This input will only be used for trusted auth. Buddylist privacy will
        not be checked against reverse buddylist query if this has a value = 0
        param includeDeny: bool [Default 1]. Setting to 0 will not return watchers that has the user on their block
        lists.
        :return: тело ответа сервера
        """
        return await self.get(
            "wim/buddylist/getWatchers",
            aimsid=self.aimsid,
            r=self.getReqId(),
            f=f,
            t=t,
            **kwargs,
        )

